import { Link } from "react-router-dom";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { CheckCircle2, Circle, ChevronRight, Rocket, ExternalLink, RefreshCw, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useOnboardingLive } from "@/hooks/useCompanyLiveData";

export default function CustomerOnboarding() {
  const { data: steps, isLoading, refetch, isFetching } = useOnboardingLive();

  const completed = steps?.filter((s) => s.complete).length ?? 0;
  const total = steps?.length ?? 0;
  const pct = total ? Math.round((completed / total) * 100) : 0;

  return (
    <div className="container mx-auto px-4 py-8 max-w-4xl">
      <div className="mb-6 flex items-center gap-2 text-xs text-muted-foreground">
        <Link to="/hub" className="hover:text-cyan-400">Platform Hub</Link>
        <ChevronRight className="h-3 w-3" />
        <Link to="/company/customer-success" className="hover:text-cyan-400">Customer Success</Link>
        <ChevronRight className="h-3 w-3" />
        <span className="text-teal-400">Onboarding Hub</span>
      </div>

      <div className="flex items-start justify-between gap-4 mb-8">
        <div className="flex items-start gap-4">
          <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-teal-500 to-emerald-600">
            <Rocket className="h-6 w-6 text-white" />
          </div>
          <div>
            <h1 className="text-2xl font-bold">Customer Onboarding Hub</h1>
            <p className="text-sm text-muted-foreground mt-1">
              Live deployment readiness — each step verified against your Supabase data
            </p>
            {!isLoading && (
              <div className="mt-4 flex items-center gap-4 max-w-md">
                <Progress value={pct} className="flex-1 h-2" />
                <Badge variant="outline">{completed}/{total} complete</Badge>
              </div>
            )}
          </div>
        </div>
        <Button variant="outline" size="sm" onClick={() => refetch()} disabled={isFetching}>
          {isFetching ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
        </Button>
      </div>

      {isLoading ? (
        <p className="text-sm text-muted-foreground animate-pulse">Loading live onboarding checks…</p>
      ) : (
        <div className="space-y-3">
          {steps?.map((step, i) => (
            <Card key={step.id} className={step.complete ? "border-emerald-500/20 bg-emerald-500/5" : ""}>
              <CardContent className="py-4 flex items-start gap-4">
                {step.complete ? (
                  <CheckCircle2 className="h-6 w-6 text-emerald-400 shrink-0 mt-0.5" />
                ) : (
                  <Circle className="h-6 w-6 text-slate-600 shrink-0 mt-0.5" />
                )}
                <div className="flex-1 min-w-0">
                  <p className="text-xs text-muted-foreground">Step {i + 1}</p>
                  <p className="font-medium">{step.title}</p>
                  <p className="text-sm text-muted-foreground mt-0.5">{step.description}</p>
                  <p className="text-xs text-cyan-400/90 mt-2 font-mono">{step.liveDetail}</p>
                  <Button variant="link" size="sm" className="px-0 h-auto mt-1" asChild>
                    <Link to={step.link}>
                      {step.linkLabel} <ExternalLink className="h-3 w-3 ml-1 inline" />
                    </Link>
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}
